function DayTimelinePreview({ title, subtitle, accentColor, onGenerate, btnLabel }) {
  const maxEnergy = 9
  return (
    <div style={{ maxWidth: 580, margin: '0 auto', padding: '8px 0', width: '100%' }}>
      <div style={{ textAlign: 'center', marginBottom: 20 }}>
        <div style={{ fontSize: 9, color: accentColor || C.gold, letterSpacing: 2, textTransform: 'uppercase', marginBottom: 4 }}>14-Moment Day Arc</div>
        <div style={{ fontSize: 11, color: C.muted }}>{subtitle}</div>
      </div>

      {/* Lighting gradient bar */}
      <div style={{ height: 6, borderRadius: 3, marginBottom: 6, background: `linear-gradient(90deg, ${DAY_MOMENTS_PREVIEW.map(m => m.light).join(', ')})`, opacity: 0.7 }} />

      {/* Energy arc bars */}
      <div style={{ display: 'flex', gap: 2, alignItems: 'flex-end', height: 36, marginBottom: 4 }}>
        {DAY_MOMENTS_PREVIEW.map((m, i) => (
          <div key={i} title={`${m.time} ${m.label}`} style={{ flex: 1, borderRadius: '2px 2px 0 0', background: m.light, opacity: 0.6 + (m.energy / maxEnergy) * 0.4, height: `${(m.energy / maxEnergy) * 100}%`, transition: 'height 0.3s', minHeight: 4 }} />
        ))}
      </div>

      {/* Timeline dots + times */}
      <div style={{ display: 'flex', gap: 2, alignItems: 'center', marginBottom: 8 }}>
        {DAY_MOMENTS_PREVIEW.map((m, i) => (
          <div key={i} style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2 }}>
            <div style={{ width: 5, height: 5, borderRadius: '50%', background: m.light, opacity: 0.8 }} />
            {(i === 0 || i === 4 || i === 9 || i === 13) && (
              <div style={{ fontSize: 6, color: C.muted, whiteSpace: 'nowrap' }}>{m.time}</div>
            )}
          </div>
        ))}
      </div>

      {/* Phase labels */}
      <div style={{ display: 'flex', gap: 4, marginBottom: 16 }}>
        {[
          { label: 'Dawn',      color: '#3a4a7a', span: 2 },
          { label: 'Morning',   color: '#c8a84b', span: 2 },
          { label: 'Midday',    color: '#e0d8c0', span: 2 },
          { label: 'Afternoon', color: '#c8b870', span: 2 },
          { label: 'Golden',    color: '#e06428', span: 2 },
          { label: 'Evening',   color: '#4a3878', span: 2 },
          { label: 'Night',     color: '#1a1238', span: 2 },
        ].map(p => (
          <div key={p.label} style={{ flex: p.span, textAlign: 'center', padding: '3px 0', borderRadius: 3, background: p.color + '28', border: `1px solid ${p.color}40` }}>
            <span style={{ fontSize: 7, fontWeight: 700, color: p.color, textTransform: 'uppercase', letterSpacing: 0.8 }}>{p.label}</span>
          </div>
        ))}
      </div>

      {/* What gets generated */}
      <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap', marginBottom: 16, justifyContent: 'center' }}>
        {['Hook per scene', 'Image prompt', 'Video direction', 'Caption', 'Posting slot'].map(item => (
          <span key={item} style={{ fontSize: 9, color: C.secondary, background: C.raised, border: `1px solid ${C.hairline}`, borderRadius: 3, padding: '2px 8px' }}>{item}</span>
        ))}
      </div>

      <div style={{ display: 'flex', justifyContent: 'center' }}>
        <button onClick={onGenerate} style={{ padding: '10px 28px', borderRadius: 8, fontSize: 12, fontWeight: 700, cursor: 'pointer', border: `1px solid ${(accentColor || C.gold) + '80'}`, background: (accentColor || C.gold) + '14', color: accentColor || C.gold, letterSpacing: 0.3 }}>
          {btnLabel}
        </button>
      </div>
    </div>
  )
}

function AdLoadingState({ outputType }) {
  const [lineIndex, setLineIndex] = useState(0)
  const [tick, setTick] = useState(0)
  useEffect(() => {
    const a = setInterval(() => setLineIndex(i => (i + 1) % LOADING_LINES.length), 2200)
    const b = setInterval(() => setTick(t => t + 1), 500)
    return () => { clearInterval(a); clearInterval(b) }
  }, [])
  const dots = '.'.repeat((tick % 3) + 1)
  return (
    <div style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 24, padding: '60px 40px', textAlign: 'center' }}>
      <div style={{ fontSize: 40 }}>{outputType === 'video' ? '🎬' : '📣'}</div>
      <div>
        <div style={{ fontSize: 14, fontWeight: 700, color: C.primary, marginBottom: 8, letterSpacing: 0.3 }}>
          Creating your ad creative{dots}
        </div>
        <div style={{ fontSize: 11, color: C.gold, letterSpacing: 0.5 }}>{LOADING_LINES[lineIndex]}</div>
      </div>
      <div style={{ padding: '8px 16px', borderRadius: 4, background: C.raised, border: `1px solid ${C.subtle}`, fontSize: 10, color: C.muted }}>
        {outputType === 'video' ? '🎬 Video takes ~2 minutes' : '🖼 Image takes ~30 seconds'}
      </div>
    </div>
  )
}

function OrchestrationProgress({ steps, currentStep, title }) {
  const [tick, setTick] = useState(0)
  useEffect(() => {
    const t = setInterval(() => setTick(n => n + 1), 500)
    return () => clearInterval(t)
  }, [])
  const dots = ['   ', '.  ', '.. ', '...'][(tick % 4)]
  const currentIdx = steps.findIndex(s => s.id === currentStep)
  return (
    <div style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 28, padding: '40px 28px' }}>
      <div style={{ textAlign: 'center' }}>
        <div style={{ fontSize: 10, color: C.gold, letterSpacing: 2, textTransform: 'uppercase', marginBottom: 6 }}>
          {title || 'AI Director is working'}
        </div>
        <div style={{ fontSize: 11, color: C.muted, letterSpacing: 4, fontFamily: C.mono }}>{dots}</div>
      </div>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 0, width: '100%', maxWidth: 280 }}>
        {steps.map((step, i) => {
          const isDone   = i < currentIdx
          const isActive = i === currentIdx
          return (
            <div key={step.id}>
              <div style={{
                display: 'flex', alignItems: 'center', gap: 10, padding: '7px 10px',
                borderRadius: 6,
                background: isActive ? C.raised : 'transparent',
                border: `1px solid ${isActive ? C.subtle : 'transparent'}`,
                transition: 'all 0.4s',
              }}>
                <div style={{
                  width: 20, height: 20, borderRadius: '50%', flexShrink: 0,
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                  fontSize: isDone ? 9 : 10, fontWeight: 800,
                  background: isDone ? C.goldGlow : isActive ? '#1a1030' : C.raised,
                  border: `1px solid ${isDone ? C.goldDim : isActive ? C.violet : C.hairline}`,
                  color: isDone ? C.gold : isActive ? C.violet : C.muted,
                  transition: 'all 0.4s',
                }}>
                  {isDone ? '✓' : step.icon}
                </div>
                <div style={{ flex: 1 }}>
                  <div style={{
                    fontSize: 10, fontWeight: isActive ? 700 : 400,
                    color: isDone ? C.secondary : isActive ? C.primary : C.muted,
                    transition: 'color 0.4s',
                  }}>{step.label}</div>
                  {isActive && step.desc && (
                    <div style={{ fontSize: 8, color: C.gold, marginTop: 2 }}>{step.desc}</div>
                  )}
                </div>
                {isActive && (
                  <div style={{ width: 6, height: 6, borderRadius: '50%', background: C.violet, opacity: tick % 2 === 0 ? 1 : 0.2, transition: 'opacity 0.5s' }} />
                )}
              </div>
              {i < steps.length - 1 && (
                <div style={{ paddingLeft: 19, fontSize: 8, color: isDone ? C.goldDim : C.hairline, lineHeight: '12px' }}>│</div>
              )}
            </div>
          )
        })}
      </div>
    </div>
  )
}

