        body: JSON.stringify({
          testName: test.name, hypothesis: test.hypothesis,
          hookA: test.hookA, hookB: test.hookB,
          hookACtr: parseFloat(test.ctrA), hookBCtr: parseFloat(test.ctrB),
          winner: test.winner, adConfig: buildAdConfig(),
        }),
