function SubjectTraits({ label, traits, accentColor, onChange, onToggleLock, isMale }) {
  const fields = isMale ? TRAIT_FIELDS_MALE : TRAIT_FIELDS_FEMALE

  return (
    <div style={{
      background: C.void,
      border: `1px solid ${accentColor}33`,
      borderLeft: `2px solid ${accentColor}`,
      borderRadius: 4,
      padding: '8px 9px',
      display: 'flex',
      flexDirection: 'column',
      gap: 3,
    }}>
      <div style={{
        fontSize: 9, fontWeight: 700, letterSpacing: 1.2,
        textTransform: 'uppercase', color: accentColor, marginBottom: 4,
      }}>
        {label}
      </div>
      {fields.map(({ key, label: fl, placeholder }) => {
        const locked = traits?.locked?.[key] || false
        const libKey = isMale && DNA_LIBRARIES[`${key}_male`] ? `${key}_male` : key
        const library = DNA_LIBRARIES[libKey] || []

        return (
          <div key={key} style={{
            display: 'flex', flexDirection: 'column', gap: 2,
            padding: '4px 0', borderBottom: `1px solid #0a0a0a`,
          }}>
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
              <span style={{
                fontSize: 9, fontWeight: 700,
                color: locked ? accentColor : C.muted,
                textTransform: 'uppercase', letterSpacing: 0.5,
              }}>
                {fl}
              </span>
              <button
                onClick={() => onToggleLock(key)}
                title={locked ? 'Unlock' : 'Lock'}
                style={{
                  background: 'transparent', border: 'none',
                  cursor: 'pointer', fontSize: 9,
                  color: locked ? accentColor : C.ghost,
                  padding: 0, lineHeight: 1,
                }}
              >
                {locked ? '🔒' : '○'}
              </button>
            </div>
            {library.length > 0 && !locked && (
              <select
                value=""
                onChange={e => { if (e.target.value) onChange(key, e.target.value) }}
                style={{
                  width: '100%', background: C.raised, color: C.secondary,
                  border: `1px solid ${C.hairline}`, borderRadius: 3,
                  padding: '3px 5px', fontSize: 9, outline: 'none',
                  fontFamily: 'inherit',
                }}
              >
                <option value="">Pick from library…</option>
                {library.map((item, i) => (
                  <option key={i} value={item}>{item}</option>
                ))}
              </select>
            )}
            <input
              style={{
                background: C.deep, color: locked ? C.muted : C.primary,
                border: `1px solid ${C.hairline}`,
                borderRadius: 3, fontSize: 10, outline: 'none',
                fontFamily: 'inherit', padding: '3px 6px',
              }}
              value={traits?.[key] || ''}
              onChange={e => !locked && onChange(key, e.target.value)}
              placeholder={locked ? '— locked —' : placeholder}
              readOnly={locked}
            />
          </div>
        )
      })}
    </div>
  )
}

// ─────────────────────────────────────────────────────────────
// ORCHESTRATION SUGGESTIONS PANEL (Build 3)
// ─────────────────────────────────────────────────────────────

function OrchestrationPanel({ s, activeBrandProfile }) {
  const [recs,    setRecs]    = useState([])
  const [loading, setLoading] = useState(false)
  const [loaded,  setLoaded]  = useState(false)

  const load = async () => {
    if (loading) return
    setLoading(true)
    try {
      // Detect type from active context
      const type = s.adConfig?.instantType || s.adConfig?.adStyle || 'creator'
      const res = await fetch('/api/orchestration-engine', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ type }),
      })
      const data = await res.json()
      if (data.recommendations) { setRecs(data.recommendations); setLoaded(true) }
    } catch {}
    setLoading(false)
  }

  const CONF_COLOR = { high: C.green, medium: C.gold, low: C.muted }

  return (
    <Panel title="Orchestration Suggestions" hint="AI-recommended configurations based on your history" accent={C.gold} defaultOpen={false}>
      {!loaded ? (
        <div style={{ textAlign: 'center', padding: '4px 0' }}>
          <div style={{ fontSize: 10, color: C.muted, marginBottom: 8, lineHeight: 1.6 }}>
            {activeBrandProfile ? `Analysing context for ${activeBrandProfile.name}…` : 'Recommends optimal goal, style, and hook type for your current context.'}
          </div>
          <button
            onClick={load}
            disabled={loading}
            style={{ padding: '6px 14px', borderRadius: 4, fontSize: 10, fontWeight: 700, cursor: 'pointer', border: `1px solid ${C.goldDim}`, background: '#1a1408', color: C.gold }}
          >
            {loading ? 'Analysing…' : '✦ Get Suggestions'}
          </button>
        </div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
          {recs.map((rec, i) => (
            <div key={i} style={{ padding: '8px 10px', borderRadius: 5, background: i === 0 ? '#1a1408' : C.raised, border: `1px solid ${i === 0 ? C.goldDim : C.hairline}` }}>
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 3 }}>
                <div style={{ fontSize: 11, fontWeight: 700, color: i === 0 ? C.gold : C.primary }}>{rec.label}</div>
                <div style={{ fontSize: 8, fontWeight: 700, color: CONF_COLOR[rec.confidence] || C.muted, textTransform: 'uppercase', letterSpacing: 1 }}>{rec.confidence}</div>
              </div>
              <div style={{ fontSize: 9, color: C.muted, lineHeight: 1.5, marginBottom: 5 }}>{rec.reason}</div>
              <div style={{ display: 'flex', gap: 4, flexWrap: 'wrap' }}>
                <span style={{ fontSize: 8, padding: '1px 5px', borderRadius: 99, background: '#08101a', border: `1px solid ${C.blueDim}`, color: C.blue }}>{rec.platform}</span>
                <span style={{ fontSize: 8, padding: '1px 5px', borderRadius: 99, background: C.deep, border: `1px solid ${C.hairline}`, color: C.muted }}>{rec.style?.replace(/_/g, ' ')}</span>
                <span style={{ fontSize: 8, padding: '1px 5px', borderRadius: 99, background: C.deep, border: `1px solid ${C.hairline}`, color: C.muted }}>{rec.hookType} hooks</span>
              </div>
            </div>
          ))}
          <button onClick={load} disabled={loading} style={{ padding: '4px 0', borderRadius: 3, fontSize: 9, cursor: 'pointer', border: `1px solid ${C.hairline}`, background: 'none', color: C.muted }}>
            {loading ? 'Refreshing…' : 'Refresh'}
          </button>
        </div>
      )}
    </Panel>
  )
}

// ─────────────────────────────────────────────────────────────
// AI DIRECTOR — pure JS helpers (no API calls)
// ─────────────────────────────────────────────────────────────

function buildDirectorOpener(memory, activeBrandProfile) {
  if (!memory || memory.campaignCount === 0) return null
  const facts = []
  if (memory.campaignCount === 1)      facts.push('One campaign in the library.')
  else if (memory.campaignCount <= 5)  facts.push(`${memory.campaignCount} campaigns built.`)
  else                                  facts.push(`${memory.campaignCount} campaigns in the library.`)
  if (memory.topWorld)      facts.push(`${memory.topWorld.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase())} is your go-to world.`)
  if (memory.bestHookType)  facts.push(`${memory.bestHookType.replace(/_/g, ' ')} hooks are your strongest.`)
  if (activeBrandProfile?.name) facts.push(`Working with ${activeBrandProfile.name}.`)
  return facts.length > 0 ? facts.join(' ') + ' What are we building next?' : null
}

function buildDirectorQuickStarts(memory, activeBrandProfile) {
  const starters = []
  if (memory?.topWorld) {
    const wLabel = memory.topWorld.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase())
    starters.push({ label: `☀ Perfect Day — ${wLabel}`, msg: `Create a perfect day in ${memory.topWorld.replace(/_/g, ' ')} for my brand` })
  } else {
    starters.push({ label: '☀ Perfect Day in Maldives', msg: 'Create a perfect day in Maldives Villa for my luxury lifestyle brand' })
  }
  if (activeBrandProfile?.name) {
    starters.push({ label: `◈ Campaign for ${activeBrandProfile.name}`, msg: `Build a full 30-day ad campaign for ${activeBrandProfile.name}` })
  } else {
    starters.push({ label: '◈ Full Ad Campaign', msg: 'Build a full 30-day ad campaign for my brand' })
  }
  starters.push({ label: '🎬 Full Day Video', msg: 'Make a full cinematic day video for my personal brand' })
  if (memory?.bestPlatform && memory.bestPlatform !== 'instagram') {
    const pLabel = memory.bestPlatform.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase())
    starters.push({ label: `⚡ ${pLabel} Campaign`, msg: `Create a quick ${memory.bestPlatform.replace(/_/g, ' ')} campaign for my brand` })
  } else {
    starters.push({ label: '⚡ Instant Campaign', msg: 'Create a quick campaign for my product launch' })
  }
  starters.push({ label: '◧ Generate Image', msg: 'Create a cinematic luxury lifestyle image for my feed' })
  return starters.slice(0, 5)
}

